			if pkt.StreamIndex() == currentInputStream.Index() {
				// Rescale timestamps from input to output time base
				pkt.RescaleTs(currentInputStream.TimeBase(), outputStream.TimeBase())

				// Apply the calculated offset
				pkt.SetPts(pkt.Pts() + ptsOffset)
				pkt.SetDts(pkt.Dts() + ptsOffset)

