}

func transcodeAndMux(octx *astiav.FormatContext, ostream *astiav.Stream, ictx *astiav.FormatContext, istream *astiav.Stream, ptsOffset int64) (err error) {
	// Setup Decoder
	dec := astiav.FindDecoder(istream.CodecParameters().CodecID())
	if dec == nil {
		return errors.New("finding decoder failed")
	}
	decCtx := astiav.AllocCodecContext(dec)
	if decCtx == nil {
		return errors.New("allocating decoder context failed")
	}
	defer decCtx.Free()
	if err = istream.CodecParameters().ToCodecContext(decCtx); err != nil {
		return fmt.Errorf("copying decoder parameters failed: %w", err)
	}
	if err = decCtx.Open(dec, nil); err != nil {
		return fmt.Errorf("opening decoder context failed: %w", err)
	}

	// Setup Encoder
	enc := astiav.FindEncoder(ostream.CodecParameters().CodecID())
	if enc == nil {
		return errors.New("finding encoder failed")
	}
	encCtx := astiav.AllocCodecContext(enc)
	if encCtx == nil {
		return errors.New("allocating encoder context failed")
	}
	defer encCtx.Free()
	encCtx.SetSampleRate(ostream.CodecParameters().SampleRate())
	encCtx.SetSampleFormat(ostream.CodecParameters().SampleFormat())
	encCtx.SetChannelLayout(ostream.CodecParameters().ChannelLayout())
	encCtx.SetTimeBase(ostream.TimeBase())
	if err = encCtx.Open(enc, nil); err != nil {
		return fmt.Errorf("opening encoder context failed: %w", err)
	}

	// Setup Filter Graph
	filterGraph := astiav.AllocFilterGraph()
	if filterGraph == nil {
		return errors.New("allocating filter graph failed")
	}
	defer filterGraph.Free()

	filterStr := fmt.Sprintf("aresample=%d,aformat=sample_fmts=%s:channel_layouts=%s",
		encCtx.SampleRate(), encCtx.SampleFmt().Name(), encCtx.ChannelLayout().String())
	log.Printf("Using filter graph: %s", filterStr)

	args := astiav.NewFilterGraphParseArgs()
	args.SetSampleFmt(decCtx.SampleFmt())
	args.SetSampleRate(decCtx.SampleRate())
	args.SetTimeBase(decCtx.TimeBase())
	args.SetChannelLayout(decCtx.ChannelLayout())

	if err = filterGraph.Parse(filterStr, args); err != nil {
		return fmt.Errorf("parsing filter graph failed: %w", err)
	}
	if err = filterGraph.Configure(); err != nil {
		return fmt.Errorf("configuring filter graph failed: %w", err)
	}

	// Start processing
	inPkt := astiav.AllocPacket()
	defer inPkt.Free()
	frame := astiav.AllocFrame()
	defer frame.Free()

	// Main loop: Read from input -> Decode -> Filter -> Encode -> Write to output
	for {
		err = ictx.ReadFrame(inPkt)
		if err != nil {
			if errors.Is(err, astiav.ErrEof) {
				break // End of input file
			}
			return fmt.Errorf("reading frame failed: %w", err)
		}

		if inPkt.StreamIndex() == istream.Index() {
			if err = processPacket(inPkt, decCtx, encCtx, filterGraph, octx, ostream, ptsOffset); err != nil {
				return err
			}
		}
		inPkt.Unref()
	}

	// Flush the remaining data in the pipeline
	if err = flushPipeline(decCtx, encCtx, filterGraph, octx, ostream, ptsOffset); err != nil {
		return err
	}

	return nil
}

// processPacket handles one packet through the decode->filter->encode->mux pipeline
func processPacket(pkt *astiav.Packet, decCtx, encCtx *astiav.CodecContext, filterGraph *astiav.FilterGraph, octx *astiav.FormatContext, ostream *astiav.Stream, ptsOffset int64) error {
	if err := decCtx.SendPacket(pkt); err != nil {
		return fmt.Errorf("sending packet to decoder failed: %w", err)
	}

	frame := astiav.AllocFrame()
	defer frame.Free()

	for {
		err := decCtx.ReceiveFrame(frame)
		if err != nil {
			if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
				break
			}
			return fmt.Errorf("receiving frame from decoder failed: %w", err)
		}

		if err := filterAndEncode(frame, encCtx, filterGraph, octx, ostream, ptsOffset); err != nil {
			return err
		}
		frame.Unref()
	}
	return nil
}

// flushPipeline sends nil to flush decoder and encoder and processes the remaining frames/packets
func flushPipeline(decCtx, encCtx *astiav.CodecContext, filterGraph *astiav.FilterGraph, octx *astiav.FormatContext, ostream *astiav.Stream, ptsOffset int64) error {
	// Flush decoder
	if err := processPacket(nil, decCtx, encCtx, filterGraph, octx, ostream, ptsOffset); err != nil {
		return err
	}

	// Flush encoder
	if err := encCtx.SendFrame(nil); err != nil {
		return fmt.Errorf("flushing encoder failed: %w", err)
	}

	outPkt := astiav.AllocPacket()
	defer outPkt.Free()

	for {
		err := encCtx.ReceivePacket(outPkt)
		if err != nil {
			if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
				break
			}
			return fmt.Errorf("receiving packet from encoder failed: %w", err)
		}

		if err := writePacket(outPkt, encCtx, octx, ostream, ptsOffset); err != nil {
			return err
		}
		outPkt.Unref()
	}
	return nil
}

// filterAndEncode handles one frame through the filter->encode->mux pipeline
func filterAndEncode(frame *astiav.Frame, encCtx *astiav.CodecContext, filterGraph *astiav.FilterGraph, octx *astiav.FormatContext, ostream *astiav.Stream, ptsOffset int64) error {
	if err := filterGraph.Buffersrc().AddFrame(frame, astiav.NewBuffersrcFlags()); err != nil {
		return fmt.Errorf("adding frame to filter graph failed: %w", err)
	}

	filteredFrame := astiav.AllocFrame()
	defer filteredFrame.Free()

	for {
		err := filterGraph.Buffersink().GetFrame(filteredFrame, astiav.NewBuffersinkFlags()); err != nil {
			if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
				break
			}
			return fmt.Errorf("getting frame from filter graph failed: %w", err)
		}

		if err := encCtx.SendFrame(filteredFrame); err != nil {
			return fmt.Errorf("sending frame to encoder failed: %w", err)
		}
		filteredFrame.Unref()

		outPkt := astiav.AllocPacket()
		defer outPkt.Free()

		for {
			err := encCtx.ReceivePacket(outPkt)
			if err != nil {
				if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
					break
				}
				return fmt.Errorf("receiving packet from encoder failed: %w", err)
			}

			if err := writePacket(outPkt, encCtx, octx, ostream, ptsOffset); err != nil {
				return err
			}
			outPkt.Unref()
		}
	}
	return nil
}

// writePacket adjusts timestamps and writes a packet to the output context
func writePacket(pkt *astiav.Packet, encCtx *astiav.CodecContext, octx *astiav.FormatContext, ostream *astiav.Stream, ptsOffset int64) error {
	pkt.RescaleTs(encCtx.TimeBase(), ostream.TimeBase())
	pkt.SetPts(pkt.Pts() + ptsOffset)
	pkt.SetDts(pkt.Dts() + ptsOffset)
	pkt.SetStreamIndex(ostream.Index())
	pkt.SetPos(-1)

	if err := octx.WriteInterleavedFrame(pkt); err != nil {
		log.Printf("Warning: writing frame failed: %v\n", err)
	}
	return nil
}

